import junit.framework.TestCase;

public class AgentBRT_Lang_48_ast_edit_Test extends TestCase {

    public void testReproduceBug() {
        EqualsBuilder builder = new EqualsBuilder();

        // Create two objects, one of which is null
        Object obj1 = new Object();
        Object obj2 = null;

        // Append these objects to the builder
        builder.append(obj1, obj2);

        // The expected behavior is that these objects are not equal
