package org.apache.commons.lang.builder;

import org.junit.Test;
import static org.junit.Assert.*;

public class AgentBRT_Lang_48_ast_edit_Test {

    @Test
    public void testReproduceBug() {
        EqualsBuilder builder = new EqualsBuilder();

        // Create two arrays of different dimensions
        int[] array1 = {1, 2, 3};
        int[][] array2 = {{1, 2, 3}};

        // Append these arrays to the builder
        builder.append(array1, array2);

        // The expected behavior is that these arrays are not equal
        // because they have different dimensions
        assertFalse("Arrays of different dimensions should not be equal", builder.isEquals());
    }
}

